shortcuts.codeOnPrepare:
/*{input_text}*/

let linkSani = '';

// 1. Grab text from the Share Sheet variable
const link = getVariable(/*[variable]*/"e6f2aae4-647d-4e8b-ab4c-6800937a67f1"/*[/variable]*/);

// 2. Strip everything from '?' or '&' onward (removes tracking parameters)

if (link.includes("youtube") && link.includes("&")){
linkSani = link.split('&')[0].trim();
}
else{
linkSani = link.split('?')[0].trim();
}


// Quick visual confirmation that the script fired
showToast('Cleaned: ' + linkSani);

// 3. Output directly via Android's native Share Sheet
shareText(linkSani);
